1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.OwnerIdentityDuplicateException;
7	
8	/**
9	 * The single duplicate-detection step: rejects the create only when the new owner's WHOLE
10	 * derived {@link OwnerIdentity#identityKey identityKey} (telephone|email|householdId) equals
11	 * an existing owner's. This consolidates the former separate telephone, email and household
12	 * duplicate checks into one key.
13	 *
14	 * <p>Runs after {@link AssignHouseholdId}, so the new owner already carries its
15	 * {@code householdId} and every existing household member has been back-filled with it — the
16	 * household segment of both keys is therefore in sync. Because the telephone is part of the
17	 * key, two members of the same household with different telephones have different keys and are
18	 * both allowed; only an exact full-key match is rejected 409 via
19	 * {@link OwnerIdentityDuplicateException}.
20	 */
21	public class RequireUniqueOwnerIdentity {
22	
23	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
24	            throws OwnerIdentityDuplicateException {
25	        String key = OwnerIdentity.identityKey(owner.getTelephone(), owner.getEmail(),
26	                owner.getHouseholdId());
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
29	                continue; // never compare the new owner against itself
30	            }
31	            if (Boolean.TRUE.equals(existing.getDeleted())) {
32	                continue; // a soft-deleted owner does not block a new one
33	            }
34	            String other = OwnerIdentity.identityKey(existing.getTelephone(), existing.getEmail(),
35	                    existing.getHouseholdId());
36	            if (key.equals(other)) {
37	                throw new OwnerIdentityDuplicateException(key);
38	            }
39	        }
40	    }
41	}
