1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Assigns the deterministic {@code householdId}: the first 12 hex characters of SHA-256 over
12	 * {@code normalizedLastName + '|' + postcode}, where the last name is normalized the same way
13	 * {@link RequireUniqueOwnerHousehold} compares it (case-insensitive, whitespace collapsed).
14	 *
15	 * <p>Because the value is derived purely from the household identity (lastName, postcode), every
16	 * owner is assigned one and owners with the same lastName and postcode share it automatically,
17	 * regardless of creation order and independent of whether the request opted into
18	 * {@code sharesHousehold}. No back-fill of existing owners is needed — they already carry the
19	 * same computed value.
20	 *
21	 * <p>Runs after {@link BuildOwner} (so the owner carries its lastName and postcode) and before
22	 * {@link RequireUniqueOwnerHousehold duplicate detection}, {@link AssignHouseholdSize the
23	 * household-size count} and {@link RequireUniqueOwnerIdentity the identity key}, all of which key
24	 * off this computed identifier.
25	 */
26	public class AssignHouseholdId {
27	
28	    public void service(@Val Owner owner) {
29	        owner.setHouseholdId(deriveHouseholdId(owner.getLastName(), owner.getPostcode()));
30	    }
31	
32	    /** First 12 lower-case hex chars of SHA-256(normalizedLastName + '|' + postcode). */
33	    static String deriveHouseholdId(String lastName, String postcode) {
34	        String key = RequireUniqueOwnerHousehold.normalize(lastName) + "|"
35	                + (postcode == null ? "" : postcode.trim());
36	        try {
37	            byte[] digest = MessageDigest.getInstance("SHA-256")
38	                    .digest(key.getBytes(StandardCharsets.UTF_8));
39	            StringBuilder sb = new StringBuilder();
40	            for (int i = 0; i < 6; i++) {
41	                sb.append(String.format("%02x", digest[i]));
42	            }
43	            return sb.toString();
44	        }
45	        catch (NoSuchAlgorithmException ex) {
46	            throw new IllegalStateException("SHA-256 not available", ex);
47	        }
48	    }
49	}
