1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Flags a soft (possible) duplicate. An owner that is not a hard identity duplicate (that check
10	 * runs earlier and rejects with 409) but that shares an existing owner's {@code lastName}
11	 * (case-insensitive) and {@code postcode} is still created, with {@code possibleDuplicate} set true
12	 * and {@code possibleDuplicateOf} set to the matching owner's id. When several owners match, the
13	 * earliest (lowest id) is chosen. Otherwise {@code possibleDuplicate} is false and
14	 * {@code possibleDuplicateOf} is absent.
15	 *
16	 * <p>A declared household member — the request set {@code sharesHousehold} true, so it was
17	 * knowingly allowed past {@link RequireUniqueOwnerHousehold} despite sharing a lastName and
18	 * postcode — is not a suspected duplicate, so it is never flagged.
19	 *
20	 * <p>Runs before {@link SaveOwner}, so the new owner is not yet persisted and only pre-existing
21	 * owners are considered.
22	 */
23	public class AssignPossibleDuplicate {
24	
25	    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
26	            OwnerRepository ownerRepository) {
27	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
28	            owner.setPossibleDuplicate(false);
29	            owner.setPossibleDuplicateOf(null);
30	            return; // a declared household member is not a suspected duplicate
31	        }
32	        String lastName = owner.getLastName();
33	        String postcode = owner.getPostcode();
34	        Integer matchId = null;
35	        if (postcode != null && !postcode.isBlank()) {
36	            for (Owner existing : ownerRepository.findAll()) {
37	                if (existing.getId() == null || existing.getId().equals(owner.getId())) {
38	                    continue; // never match the new owner against itself
39	                }
40	                if (Boolean.TRUE.equals(existing.getDeleted())) {
41	                    continue; // a soft-deleted owner is not a possible duplicate
42	                }
43	                if (equalsIgnoreCase(existing.getLastName(), lastName)
44	                        && postcode.equals(existing.getPostcode())) {
45	                    if (matchId == null || existing.getId() < matchId) {
46	                        matchId = existing.getId();
47	                    }
48	                }
49	            }
50	        }
51	        owner.setPossibleDuplicate(matchId != null);
52	        owner.setPossibleDuplicateOf(matchId);
53	    }
54	
55	    private static boolean equalsIgnoreCase(String a, String b) {
56	        return a == null ? b == null : a.equalsIgnoreCase(b);
57	    }
58	}
