1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.OwnerHouseholdDuplicateException;
8	
9	/**
10	 * Rejects the create when another owner already belongs to this owner's household — the same
11	 * computed {@link AssignHouseholdId#deriveHouseholdId householdId}, which is derived from the
12	 * (lastName, postcode) pair. Owners sharing a lastName and postcode are the same household, so a
13	 * second such owner is rejected 409 via {@link OwnerHouseholdDuplicateException}.
14	 *
15	 * <p>Bypassed when the request sets {@code sharesHousehold} true — the caller has confirmed the
16	 * two owners knowingly live together. Such a declared member is then created (and, sharing the
17	 * computed householdId, becomes part of the household) rather than blocked.
18	 *
19	 * <p>Also admitted is a new owner that identifies itself as a distinct member by supplying its
20	 * own non-blank email that no existing member of the household already holds: a distinct email
21	 * marks a genuinely separate person rather than a re-submission of the same one. A member with no
22	 * email, or one whose email is already held by a member, is still rejected as a duplicate.
23	 *
24	 * <p>Runs after {@link AssignHouseholdId}, so the owner already carries its computed
25	 * {@code householdId} and every existing member carries the same value.
26	 */
27	public class RequireUniqueOwnerHousehold {
28	
29	    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
30	            OwnerRepository ownerRepository) throws OwnerHouseholdDuplicateException {
31	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
32	            return;
33	        }
34	        String householdId = owner.getHouseholdId();
35	        if (householdId == null) {
36	            return;
37	        }
38	        String email = normalizeEmail(owner.getEmail());
39	        for (Owner existing : ownerRepository.findAll()) {
40	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
41	                continue; // never match the new owner against itself
42	            }
43	            if (Boolean.TRUE.equals(existing.getDeleted())) {
44	                continue; // a soft-deleted owner does not block a new one
45	            }
46	            if (!householdId.equals(existing.getHouseholdId())) {
47	                continue;
48	            }
49	            // Same household: a duplicate unless this owner is distinguished by its own,
50	            // non-blank email that this existing member does not share.
51	            if (email.isEmpty() || email.equals(normalizeEmail(existing.getEmail()))) {
52	                throw new OwnerHouseholdDuplicateException(request.getLastName(),
53	                        request.getAddress());
54	            }
55	        }
56	    }
57	
58	    /** Lower-cased, trimmed email; empty string for a null or blank value. */
59	    private static String normalizeEmail(String email) {
60	        return (email == null || email.isBlank()) ? "" : email.trim().toLowerCase();
61	    }
62	
63	    /** Lower-case, trimmed, with internal whitespace runs collapsed to a single space. */
64	    static String normalize(String value) {
65	        if (value == null) {
66	            return "";
67	        }
68	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
69	    }
70	}
