package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.OwnerIdentityDuplicateException;

/**
 * The single duplicate-detection step: rejects the create only when the new owner's WHOLE
 * derived {@link OwnerIdentity#identityKey identityKey} (telephone|email|householdId) equals
 * an existing owner's. This consolidates the former separate telephone, email and household
 * duplicate checks into one key.
 *
 * <p>Runs after {@link AssignHouseholdId}, so the new owner already carries its
 * {@code householdId} and every existing household member has been back-filled with it — the
 * household segment of both keys is therefore in sync. Because the telephone is part of the
 * key, two members of the same household with different telephones have different keys and are
 * both allowed; only an exact full-key match is rejected 409 via
 * {@link OwnerIdentityDuplicateException}.
 */
public class RequireUniqueOwnerIdentity {

    public void service(@Val Owner owner, OwnerRepository ownerRepository)
            throws OwnerIdentityDuplicateException {
        String key = OwnerIdentity.identityKey(owner.getTelephone(), owner.getEmail(),
                owner.getHouseholdId());
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
                continue; // never compare the new owner against itself
            }
            if (Boolean.TRUE.equals(existing.getDeleted())) {
                continue; // a soft-deleted owner does not block a new one
            }
            String other = OwnerIdentity.identityKey(existing.getTelephone(), existing.getEmail(),
                    existing.getHouseholdId());
            if (key.equals(other)) {
                throw new OwnerIdentityDuplicateException(key);
            }
        }
    }
}

package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
import org.springframework.samples.petclinic.rest.function.owner.OwnerRegion;

import java.util.Collection;
import java.util.List;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    @Mapping(target = "displayName",
        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "initials",
        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
    @Mapping(target = "salutation",
        expression = "java(composeSalutation(owner))")
    @Mapping(target = "locality",
        expression = "java(deriveLocality(owner))")
    @Mapping(target = "timezone",
        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerTimezone.fromRegion(deriveLocality(owner)))")
    @Mapping(target = "contactPreference",
        expression = "java(owner.getEmail() != null && !owner.getEmail().isBlank() ? \"EMAIL\" : \"PHONE\")")
    @Mapping(target = "identityKey",
        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.identityKey(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId()))")
    @Mapping(target = "checkDigit",
        expression = "java(luhnCheckDigit(owner.getCustomerCode()))")
    @Mapping(target = "ageBand",
        expression = "java(org.springframework.samples.petclinic.rest.function.owner.AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate()))")
    @Mapping(target = "fiscalYear",
        expression = "java(org.springframework.samples.petclinic.rest.function.owner.FiscalYear.label(owner.getRegistrationDate()))")
    @Mapping(target = "telephoneDisplay",
        expression = "java(org.springframework.samples.petclinic.rest.function.owner.TelephoneDisplay.of(owner.getTelephone()))")
    @Mapping(target = "selfLink",
        expression = "java(\"/api/owners/\" + owner.getId())")
    OwnerDto toOwnerDto(Owner owner);

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    /**
     * Derives the owner's locality (region) from the region-and-hash identity: the {@code <REGION>}
     * segment of the {@code <REGION>-<HASH8>} {@code customerCode}. The region embedded in the code
     * is itself derived (postcode preferred, then city) when the owner is created, so a postcode in a
     * known range still wins over the city. When no such code is present (e.g. legacy owners), falls
     * back to deriving the region live from the postcode/city via {@link OwnerRegion}.
     */
    default String deriveLocality(Owner owner) {
        String code = owner.getCustomerCode();
        if (code != null) {
            int dash = code.indexOf('-');
            if (dash > 0) {
                return code.substring(0, dash);
            }
        }
        return OwnerRegion.fromPostcodeOrCity(owner.getPostcode(), owner.getCity());
    }

    /**
     * Computes the single Luhn check digit (0-9) over the digits contained in the given
     * customerCode. Non-digit characters (the separators) are ignored; from the rightmost digit
     * leftwards every second digit is doubled (subtracting 9 when the result exceeds 9), and the
     * check digit is {@code (10 - (sum % 10)) % 10}. Returns 0 when the code is null.
     */
    default int luhnCheckDigit(String customerCode) {
        if (customerCode == null) {
            return 0;
        }
        int sum = 0;
        boolean dbl = true;
        for (int i = customerCode.length() - 1; i >= 0; i--) {
            char c = customerCode.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }

    /**
     * Composes the owner's salutation: the honorific {@code title} followed by a single space and
     * the {@code lastName} when a title is supplied, or just the {@code lastName} when no title is
     * given (null or blank).
     */
    default String composeSalutation(Owner owner) {
        String title = owner.getTitle();
        if (title == null || title.isBlank()) {
            return owner.getLastName();
        }
        return title + " " + owner.getLastName();
    }

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

input.old_string:
 * Flags a soft (possible) duplicate. An owner that is not a hard identity duplicate (that check
 * runs earlier and rejects with 409) but that shares an existing owner's {@code lastName}
 * (case-insensitive) and {@code postcode} is still created, with {@code possibleDuplicate} set true
 * and {@code possibleDuplicateOf} set to the matching owner's id. When several owners match, the
 * earliest (lowest id) is chosen. Otherwise {@code possibleDuplicate} is false and
 * {@code possibleDuplicateOf} is absent.
 *
 * <p>A declared household member — the request set {@code sharesHousehold} true, so it was
 * knowingly allowed past {@link RequireUniqueOwnerHousehold} despite sharing a lastName and
 * postcode — is not a suspected duplicate, so it is never flagged.
 *
 * <p>Runs before {@link SaveOwner}, so the new owner is not yet persisted and only pre-existing
 * owners are considered.
 */
public class AssignPossibleDuplicate {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
            OwnerRepository ownerRepository) {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            owner.setPossibleDuplicate(false);
            owner.setPossibleDuplicateOf(null);
            return; // a declared household member is not a suspected duplicate
        }
        String lastName = owner.getLastName();
        String postcode = owner.getPostcode();
        Integer matchId = null;
        if (postcode != null && !postcode.isBlank()) {
            for (Owner existing : ownerRepository.findAll()) {
                if (existing.getId() == null || existing.getId().equals(owner.getId())) {
                    continue; // never match the new owner against itself
                }
                if (Boolean.TRUE.equals(existing.getDeleted())) {
                    continue; // a soft-deleted owner is not a possible duplicate
                }
                if (equalsIgnoreCase(existing.getLastName(), lastName)
                        && postcode.equals(existing.getPostcode())) {
                    if (matchId == null || existing.getId() < matchId) {
                        matchId = existing.getId();
                    }
                }
            }
        }
        owner.setPossibleDuplicate(matchId != null);
        owner.setPossibleDuplicateOf(matchId);
    }

    private static boolean equalsIgnoreCase(String a, String b) {
        return a == null ? b == null : a.equalsIgnoreCase(b);
    }
}

